const menuButton = document.querySelector('.menu-toggle');
const navigation = document.querySelector('#navigation');
function closeMenu(){navigation.classList.remove('open');menuButton.setAttribute('aria-expanded','false');menuButton.setAttribute('aria-label','メニューを開く');}
menuButton.addEventListener('click',()=>{const open=navigation.classList.toggle('open');menuButton.setAttribute('aria-expanded',String(open));menuButton.setAttribute('aria-label',open?'メニューを閉じる':'メニューを開く');});
navigation.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu();});
const content=window.CLUB_CONTENT||{};
if(content.instagramUrl){try{const url=new URL(content.instagramUrl);if(url.protocol==='https:'&&(url.hostname==='instagram.com'||url.hostname.endsWith('.instagram.com'))){const link=document.querySelector('#instagram-link');link.href=url.href;link.hidden=false;document.querySelector('#instagram-coming').hidden=true;document.querySelector('#instagram-status').textContent='活動の最新情報をチェック';document.querySelector('.contact p:not(.eyebrow)').innerHTML='活動のお知らせや日々の様子は、Instagramで。<br>筋肉部の最新情報をお届けします。';}}catch{}}
(content.photos||[]).slice(0,3).forEach((photo,i)=>{if(!photo.src)return;const figure=document.querySelectorAll('.photo-slot')[i];const img=document.createElement('img');img.src=photo.src;img.alt=photo.alt||'筋肉部の活動写真';img.loading='lazy';img.addEventListener('error',()=>img.replaceWith(placeholder),{once:true});const placeholder=figure.querySelector('.photo-placeholder');placeholder.replaceWith(img);figure.querySelector('figcaption').textContent=photo.caption||photo.alt;});
const newsItems=Array.isArray(content.news)?content.news:[];
if(newsItems.length){const list=document.querySelector('#news-list');list.replaceChildren();newsItems.forEach(item=>{const article=document.createElement('article');article.className='news-item';const meta=document.createElement('div');meta.className='news-meta';const date=document.createElement('time');date.textContent=item.date||'';if(/^\d{4}-\d{2}-\d{2}$/.test(item.date||''))date.dateTime=item.date;meta.append(date);if(item.category){const category=document.createElement('span');category.className='news-category';category.textContent=item.category;meta.append(category);}const title=document.createElement('h3');title.textContent=item.title||'';article.append(meta,title);if(item.body){const body=document.createElement('p');body.textContent=item.body;article.append(body);}list.append(article);});}
(content.founderPhotos||[]).slice(0,2).forEach((photo,i)=>{if(!photo.src)return;const slot=document.querySelector(`[data-founder-photo="${i}"]`);const img=document.createElement('img');img.alt=photo.alt||'創設メンバー';img.loading='lazy';img.addEventListener('load',()=>slot.replaceChildren(img),{once:true});img.src=photo.src;});
